-- Stage-by-stage practical learning activities and transparent assessment criteria.
-- Additive content catalogue; learner records and existing course data are not changed.

create table if not exists public.livelihood_stage_activities (
  id uuid primary key default gen_random_uuid(),
  stage_no smallint not null references public.livelihood_stages(stage_no) on delete cascade,
  activity_no smallint not null check (activity_no > 0),
  title_my text not null,
  title_en text not null,
  instructions_my text not null,
  instructions_en text not null,
  evidence_prompt_my text not null,
  evidence_prompt_en text not null,
  assessment_criteria jsonb not null default '[]'::jsonb,
  estimated_minutes smallint not null default 30 check (estimated_minutes between 5 and 600),
  sort_order smallint not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique(stage_no,activity_no),
  unique(stage_no,sort_order),
  check (jsonb_typeof(assessment_criteria) = 'array')
);

insert into public.livelihood_stage_activities
(stage_no,activity_no,title_my,title_en,instructions_my,instructions_en,evidence_prompt_my,evidence_prompt_en,assessment_criteria,estimated_minutes,sort_order)
values
(1,1,'ကျွန်ုပ်၏ အားသာချက်နှင့် အတွေ့အကြုံမြေပုံ','My Strengths & Experience Map','ပညာရေး၊ အလုပ်/စေတနာ့ဝန်ထမ်းအတွေ့အကြုံ၊ မိသားစုနှင့် လူမှုအသိုင်းအဝိုင်းတွင် လုပ်ဆောင်ခဲ့ဖူးသည့်အရာများကို စာရင်းပြုစုပါ။ မိမိဂုဏ်ယူရသော အောင်မြင်မှု ၃ ခုနှင့် အားသာချက် ၃ ခုကို ရွေးချယ်ပါ။ ကိုယ်ရေးကိုယ်တာ လျှို့ဝှက်အချက်အလက်များ မထည့်ပါနှင့်။','List your education, paid or volunteer experience, and activities you have done at home or in your community. Identify three achievements and three strengths. Do not include private identifying information.','မိမိ၏ အတွေ့အကြုံ၊ အားသာချက် ၃ ခုနှင့် ၎င်းတို့ကို အသုံးချနိုင်သည့် ဥပမာများကို ဖော်ပြပါ။','Describe your experience, three strengths and examples of how you have used them.','[{"my":"အတွေ့အကြုံ သို့မဟုတ် လုပ်ဆောင်ချက် အနည်းဆုံး ၃ ခု ပါဝင်သည်။","en":"Includes at least three experiences or activities."},{"my":"အားသာချက် ၃ ခုကို ဥပမာနှင့်တကွ ဖော်ပြထားသည်။","en":"Identifies three strengths with examples."},{"my":"ကိုယ်ရေးကိုယ်တာ လျှို့ဝှက်အချက်အလက် မပါဝင်ပါ။","en":"Does not disclose sensitive personal information."}]'::jsonb,35,1),
(1,2,'ကျွန်ုပ်၏ ရည်မှန်းချက်နှင့် လက်ရှိအခြေအနေ','My Goal & Current Situation','မိမိအတွက် အရေးကြီးသော အသက်မွေးဝမ်းကျောင်းရည်မှန်းချက်တစ်ခု ရွေးပါ။ လက်ရှိအခြေအနေ၊ လိုအပ်နေသည့် ကျွမ်းကျင်မှုနှင့် ရနိုင်သော အထောက်အပံ့တို့ကို ခွဲခြားရေးသားပါ။ မသေချာသေးပါက “စူးစမ်းလေ့လာနေဆဲ” ဟု ရွေးချယ်နိုင်သည်။','Choose one livelihood goal that matters to you. Describe your current situation, skills you still need and support available to you. If unsure, you may state that you are still exploring.','မိမိ၏ ရည်မှန်းချက်၊ လက်ရှိအခြေအနေနှင့် နောက်ထပ်သင်ယူလိုသည့်အရာ ၂ ခုကို ရေးသားပါ။','Write your goal, current situation and two things you want to learn next.','[{"my":"ရည်မှန်းချက်ကို ရှင်းလင်းစွာ ဖော်ပြထားသည် သို့မဟုတ် စူးစမ်းနေဆဲဟု ဖော်ပြထားသည်။","en":"States a clear goal or explains that they are still exploring."},{"my":"လက်ရှိအခြေအနေနှင့် လိုအပ်ချက်ကို ခွဲခြားထားသည်။","en":"Distinguishes current situation from development needs."},{"my":"နောက်တစ်ဆင့် သင်ယူမှု ၂ ခုကို သတ်မှတ်ထားသည်။","en":"Identifies two next learning needs."}]'::jsonb,30,2),
(2,1,'နေ့စဉ်ပြဿနာဖြေရှင်းမှု လေ့ကျင့်ခန်း','Everyday Problem-Solving Practice','အလုပ်၊ သင်ယူမှု သို့မဟုတ် နေ့စဉ်ဘဝတွင် ကြုံတွေ့နိုင်သော ပြဿနာတစ်ခုကို ရွေးပါ။ ဖြစ်ရသည့်အကြောင်းရင်း၊ ရွေးချယ်စရာ ဖြေရှင်းနည်း ၂ ခုနှင့် အကျိုးဆက်များကို စဉ်းစားပါ။','Choose a realistic challenge from work, learning or daily life. Consider its causes, two possible solutions and likely consequences.','ပြဿနာ၊ ဖြေရှင်းနည်း ၂ ခုနှင့် မိမိရွေးချယ်သည့်နည်းလမ်းကို အကြောင်းပြချက်နှင့် ဖော်ပြပါ။','Describe the problem, two possible solutions and your chosen approach with reasons.','[{"my":"ပြဿနာကို တိကျစွာ ဖော်ပြထားသည်။","en":"Defines the problem clearly."},{"my":"ဖြေရှင်းနည်း အနည်းဆုံး ၂ ခု စဉ်းစားထားသည်။","en":"Considers at least two possible solutions."},{"my":"ရွေးချယ်မှုအတွက် အကြောင်းပြချက် ပေးထားသည်။","en":"Explains the reason for the chosen solution."}]'::jsonb,30,1),
(2,2,'အခြေခံငွေကြေးနှင့် ဒစ်ဂျစ်တယ်လေ့ကျင့်ခန်း','Basic Money & Digital Skills Exercise','ဥပမာငွေပမာဏများကို အသုံးပြုပြီး ဝင်ငွေ၊ အသုံးစရိတ်နှင့် ကျန်ငွေကို တွက်ချက်ပါ။ ထို့နောက် မိမိအတွက် အသုံးဝင်မည့် ဒစ်ဂျစ်တယ်ကိရိယာတစ်ခုကို ရွေးပြီး ဘေးကင်းစွာ အသုံးပြုပုံကို ဖော်ပြပါ။ အမှန်တကယ် ဘဏ်အကောင့် သို့မဟုတ် စကားဝှက် မမျှဝေပါနှင့်။','Use sample amounts to calculate income, expenses and the balance. Then choose one useful digital tool and explain how to use it safely. Never share real bank details or passwords.','ဥပမာငွေစာရင်းတစ်ခုနှင့် အသုံးပြုမည့် ဒစ်ဂျစ်တယ်ကိရိယာ၊ လုံခြုံရေးသတိပြုချက် ၂ ခုကို တင်ပြပါ။','Submit a sample money record, one digital tool you would use and two safety precautions.','[{"my":"ဝင်ငွေ၊ အသုံးစရိတ်နှင့် ကျန်ငွေကို မှန်ကန်စွာ ခွဲခြားထားသည်။","en":"Correctly distinguishes income, expenses and balance."},{"my":"သင့်တော်သော ဒစ်ဂျစ်တယ်ကိရိယာတစ်ခု ရွေးထားသည်။","en":"Selects an appropriate digital tool."},{"my":"လုံခြုံရေးသတိပြုချက် ၂ ခု ပါဝင်သည်။","en":"Includes two relevant safety precautions."}]'::jsonb,40,2),
(3,1,'ကျွမ်းကျင်မှု လက်တွေ့သရုပ်ပြခြင်း','Demonstrate a Practical Skill','မိမိရွေးချယ်ထားသော လုပ်ငန်းနယ်ပယ်နှင့် ကိုက်ညီသည့် အခြေခံလုပ်ငန်းတာဝန်တစ်ခုကို လေ့ကျင့်ပါ။ ဥပမာ အစားအသောက်ပြုပြင်ထုတ်လုပ်မှု၊ အပ်ချုပ်၊ စိုက်ပျိုးရေး၊ အရောင်းအဝယ်၊ ဒစ်ဂျစ်တယ်ဝန်ဆောင်မှု သို့မဟုတ် အခြားသင့်တော်သော ကျွမ်းကျင်မှုတစ်ခု ဖြစ်နိုင်သည်။','Practise one foundational task in your chosen field. Examples include food processing, tailoring, agriculture, trading, a digital service or another relevant skill.','လုပ်ငန်းတာဝန်၊ အသုံးပြုသည့် အဆင့်များ၊ ရလဒ်နှင့် မိမိကိုယ်တိုင် သတိပြုမိသည့် အရည်အသွေးအချက်များကို ဖော်ပြပါ။','Describe the task, steps taken, result and quality points you noticed.','[{"my":"ရွေးချယ်ထားသော ကျွမ်းကျင်မှုနှင့် ကိုက်ညီသည့် လက်တွေ့တာဝန်ဖြစ်သည်။","en":"The task is relevant to the chosen skill."},{"my":"လုပ်ဆောင်သည့် အဆင့်များကို ရှင်းပြထားသည်။","en":"Explains the steps taken."},{"my":"အရည်အသွေး သို့မဟုတ် ဘေးကင်းရေးကို ထည့်သွင်းစဉ်းစားထားသည်။","en":"Considers quality or safety."}]'::jsonb,60,1),
(3,2,'ကျွမ်းကျင်မှု တိုးတက်ရေးအစီအစဉ်','My Skill Improvement Plan','မိမိလုပ်ဆောင်ခဲ့သော လက်တွေ့တာဝန်အပေါ် ပြန်လည်သုံးသပ်ပါ။ ကောင်းမွန်ခဲ့သည့်အချက် ၂ ခု၊ တိုးတက်ရန်လိုသည့်အချက် ၂ ခုနှင့် ထပ်မံလေ့ကျင့်မည့် အစီအစဉ်ကို သတ်မှတ်ပါ။','Reflect on your practical task. Identify two things that went well, two areas to improve and a plan for further practice.','မိမိ၏ အားသာချက်၊ တိုးတက်ရန်လိုသည့်အချက်နှင့် လေ့ကျင့်မည့်အချိန်ဇယားကို တင်ပြပါ။','Submit your strengths, improvement areas and a practice schedule.','[{"my":"ကောင်းမွန်ခဲ့သည့်အချက် ၂ ခု ပါဝင်သည်။","en":"Identifies two things done well."},{"my":"တိုးတက်ရန်လိုသည့်အချက် ၂ ခု ပါဝင်သည်။","en":"Identifies two improvement areas."},{"my":"လက်တွေ့ကျသော လေ့ကျင့်ရေးအစီအစဉ် ရှိသည်။","en":"Provides a realistic practice plan."}]'::jsonb,30,2),
(4,1,'ကျွမ်းကျင်မှု Portfolio တစ်ခု ပြုလုပ်ခြင်း','Create a Skills Portfolio Item','မိမိလုပ်ဆောင်ခဲ့သော အလုပ်တစ်ခုကို ရွေးပြီး Portfolio အဖြစ် စုစည်းပါ။ စာတမ်း၊ ဒီဇိုင်း၊ တွက်ချက်မှု၊ ထုတ်ကုန်နမူနာ၊ ဓာတ်ပုံ သို့မဟုတ် အခြားသင့်တော်သော အထောက်အထားကို အသုံးပြုနိုင်သည်။ အခြားသူများ၏ ကိုယ်ရေးအချက်အလက် သို့မဟုတ် ခွင့်ပြုချက်မရှိသော ပုံများ မထည့်ပါနှင့်။','Select one piece of work and present it as a portfolio item. You may use a document, design, calculation, product sample, photo or other suitable evidence. Do not include another person’s personal information or images without permission.','မိမိလုပ်ဆောင်ခဲ့သည့်အရာ၊ ရည်ရွယ်ချက်၊ လုပ်ငန်းစဉ်နှင့် ရလဒ်ကို ရှင်းပြပါ။','Explain what you created, its purpose, process and result.','[{"my":"အလုပ်နမူနာ သို့မဟုတ် ဖော်ပြနိုင်သော အထောက်အထား ပါဝင်သည်။","en":"Includes a work sample or describable evidence."},{"my":"မိမိ၏ အခန်းကဏ္ဍနှင့် လုပ်ငန်းစဉ်ကို ရှင်းပြထားသည်။","en":"Explains personal contribution and process."},{"my":"အခြားသူ၏ ကိုယ်ရေးအချက်အလက်ကို ကာကွယ်ထားသည်။","en":"Protects other people’s personal information."}]'::jsonb,60,1),
(4,2,'လက်တွေ့အခြေအနေကို ဖြေရှင်းခြင်း','Solve a Realistic Work Scenario','မိမိရွေးချယ်ထားသော လုပ်ငန်းနယ်ပယ်တွင် ကြုံတွေ့နိုင်သည့် အခြေအနေတစ်ခုကို ရွေးပါ။ ဥပမာ ဖောက်သည်တောင်းဆိုချက်၊ ထုတ်ကုန်အရည်အသွေး၊ အချိန်စီမံမှု၊ အလုပ်ခွင်ဘေးကင်းရေး သို့မဟုတ် ဝန်ဆောင်မှုအမှားတစ်ခုကို တာဝန်ယူဖြေရှင်းပုံကို ဖော်ပြပါ။','Choose a realistic situation from your field, such as a customer request, product quality issue, time management, workplace safety or service error. Explain how you would respond responsibly.','အခြေအနေ၊ ဆုံးဖြတ်ချက်၊ လုပ်ဆောင်ချက်နှင့် ရလဒ်/သင်ခန်းစာကို ဖော်ပြပါ။','Describe the situation, decision, action and result or lesson learned.','[{"my":"အခြေအနေကို လက်တွေ့ကျစွာ သတ်မှတ်ထားသည်။","en":"Defines a realistic situation."},{"my":"တာဝန်ယူမှုရှိသော ဖြေရှင်းနည်းကို ရွေးချယ်ထားသည်။","en":"Chooses a responsible response."},{"my":"ရလဒ် သို့မဟုတ် သင်ခန်းစာကို ပြန်လည်သုံးသပ်ထားသည်။","en":"Reflects on the result or lesson learned."}]'::jsonb,45,2),
(5,1,'ဝင်ငွေလမ်းကြောင်း စတင်ရေးအစီအစဉ်','Income Pathway Action Plan','မိမိအတွက် သင့်တော်သည့် လမ်းကြောင်းတစ်ခုကို ရွေးပါ — အလုပ်အကိုင်၊ အလုပ်သင်၊ Freelance၊ ကိုယ်ပိုင်လုပ်ငန်း သို့မဟုတ် ထပ်မံသင်ယူရေး။ လိုအပ်ချက်၊ အရင်းအမြစ်၊ အတားအဆီးနှင့် လာမည့် ရက် ၃၀ အတွင်း လုပ်ဆောင်မည့် အဆင့်များကို သတ်မှတ်ပါ။','Choose a suitable pathway: employment, apprenticeship, freelancing, self-employment or further learning. Identify requirements, resources, barriers and actions for the next 30 days.','ရွေးချယ်ထားသော လမ်းကြောင်း၊ လုပ်ဆောင်မည့် အဆင့် ၃ ခုနှင့် အချိန်ဇယားကို တင်ပြပါ။','Submit your chosen pathway, three actions and a timeline.','[{"my":"လမ်းကြောင်းကို မိမိအခြေအနေနှင့် ကိုက်ညီစွာ ရွေးချယ်ထားသည်။","en":"Chooses a pathway that fits the learner’s situation."},{"my":"လုပ်ဆောင်ချက် ၃ ခုနှင့် အချိန်ဇယား ပါဝင်သည်။","en":"Includes three actions and a timeline."},{"my":"လိုအပ်သော အထောက်အပံ့ သို့မဟုတ် အတားအဆီးကို သတ်မှတ်ထားသည်။","en":"Identifies needed support or barriers."}]'::jsonb,40,1),
(5,2,'အခွင့်အလမ်းတစ်ခုကို လက်တွေ့ချိတ်ဆက်ခြင်း','Take One Opportunity-Connection Action','အလုပ်ခေါ်စာတစ်ခုကို လေ့လာခြင်း၊ CV ပြင်ဆင်ခြင်း၊ အလုပ်ရှင်ထံ မေးမြန်းခြင်း၊ ဖောက်သည်တစ်ဦးနှင့် ဆွေးနွေးခြင်း သို့မဟုတ် လုပ်ငန်းစမ်းသပ်ရောင်းချခြင်းကဲ့သို့ သင့်တော်သော လုပ်ဆောင်ချက်တစ်ခုကို ရွေးပါ။ အခကြေးငွေမရသော အလုပ်ကို Paid Work ဟု မဖော်ပြပါနှင့်။','Choose one suitable action: review a vacancy, prepare a CV, contact an employer, speak with a potential customer or test a product. Never describe unpaid work as paid work.','လုပ်ဆောင်ခဲ့သည့် အဆင့်၊ ရရှိခဲ့သည့် တုံ့ပြန်ချက်နှင့် နောက်တစ်ဆင့်ကို ဖော်ပြပါ။','Describe the action taken, response received and next step.','[{"my":"အမှန်တကယ် လုပ်ဆောင်ခဲ့သည့် ချိတ်ဆက်မှုတစ်ခု ပါဝင်သည်။","en":"Shows one genuine opportunity-connection action."},{"my":"ရရှိခဲ့သည့် တုံ့ပြန်ချက်ကို မှန်ကန်စွာ ဖော်ပြထားသည်။","en":"Accurately describes the response received."},{"my":"နောက်တစ်ဆင့်ကို သတ်မှတ်ထားသည်။","en":"Identifies a realistic next step."}]'::jsonb,45,2),
(6,1,'ဝင်ငွေနှင့် အသုံးစရိတ် ပြန်လည်သုံးသပ်ခြင်း','Review Income, Costs & Stability','ကိုယ်ပိုင်လုပ်ငန်း သို့မဟုတ် အလုပ်အကိုင်အတွက် ဥပမာ/အမည်မဖော်လိုသော အချက်အလက်များကို အသုံးပြုပြီး ဝင်ငွေ၊ ကုန်ကျစရိတ်နှင့် ကျန်ငွေကို ပြန်လည်သုံးသပ်ပါ။ တည်ငြိမ်မှုကို ထိခိုက်စေနိုင်သော အန္တရာယ် ၂ ခုနှင့် လျှော့ချနိုင်မည့် နည်းလမ်းများကို ဖော်ပြပါ။','Use sample or anonymised information to review income, costs and balance for your work or enterprise. Identify two risks to stability and ways to reduce them.','ဝင်ငွေ/ကုန်ကျစရိတ် အကျဉ်းချုပ်၊ အန္တရာယ် ၂ ခုနှင့် ကာကွယ်ရေးအစီအစဉ်ကို တင်ပြပါ။','Submit an income/cost summary, two risks and a mitigation plan.','[{"my":"ဝင်ငွေနှင့် ကုန်ကျစရိတ်ကို ခွဲခြားထားသည်။","en":"Separates income and costs."},{"my":"တည်ငြိမ်မှုဆိုင်ရာ အန္တရာယ် ၂ ခု ဖော်ပြထားသည်။","en":"Identifies two stability risks."},{"my":"လက်တွေ့ကျသော ကာကွယ်ရေးနည်းလမ်း ရှိသည်။","en":"Provides practical mitigation actions."}]'::jsonb,40,1),
(6,2,'အရည်အသွေးနှင့် ထိရောက်မှု တိုးတက်ရေး','Improve Quality & Productivity','မိမိ၏ ထုတ်ကုန်၊ ဝန်ဆောင်မှု သို့မဟုတ် လုပ်ငန်းစဉ်တစ်ခုကို ရွေးပါ။ အချိန်၊ ကုန်ကျစရိတ်၊ အရည်အသွေး၊ ဖောက်သည်အတွေ့အကြုံ သို့မဟုတ် အရင်းအမြစ်အသုံးပြုမှုအနက် တစ်ခုကို တိုးတက်စေရန် အပြောင်းအလဲတစ်ခု စမ်းသပ်ပါ။','Choose a product, service or work process. Test one change to improve time, cost, quality, customer experience or resource use.','မပြောင်းလဲမီ အခြေအနေ၊ စမ်းသပ်သည့် ပြောင်းလဲမှုနှင့် ရလဒ်ကို ဖော်ပြပါ။','Describe the starting situation, change tested and result.','[{"my":"တိုးတက်စေလိုသည့် အချက်တစ်ခုကို သတ်မှတ်ထားသည်။","en":"Identifies one area for improvement."},{"my":"စမ်းသပ်လုပ်ဆောင်ချက်ကို ရှင်းပြထားသည်။","en":"Explains the improvement tested."},{"my":"ရလဒ်ကို သက်သေအထောက်အထား သို့မဟုတ် လေ့လာတွေ့ရှိချက်ဖြင့် ဖော်ပြထားသည်။","en":"Reports results with evidence or observations."}]'::jsonb,50,2),
(7,1,'People, Profit & Planet ကို ထည့်သွင်းစဉ်းစားခြင်း','Apply People, Profit & Planet','မိမိ၏ အလုပ် သို့မဟုတ် လုပ်ငန်းအတွက် People (လူများ၏ လုံခြုံမှုနှင့် ဂုဏ်သိက္ခာ)၊ Profit (ရေရှည်စီးပွားရေးဖြစ်နိုင်ခြေ)၊ Planet (ပတ်ဝန်းကျင်အပေါ် သက်ရောက်မှု) တို့ကို စဉ်းစားပါ။ တိုးတက်စေရန် လုပ်ဆောင်ချက်တစ်ခုစီ သတ်မှတ်ပါ။','Consider People (safety and dignity), Profit (long-term viability) and Planet (environmental impact) in your work or enterprise. Identify one improvement action for each.','People, Profit, Planet အတွက် လုပ်ဆောင်ချက် ၃ ခုနှင့် မည်သို့တိုင်းတာမည်ကို တင်ပြပါ။','Submit three actions—one for each pillar—and explain how you will measure them.','[{"my":"People, Profit, Planet သုံးခုစလုံးကို ထည့်သွင်းစဉ်းစားထားသည်။","en":"Considers all three pillars."},{"my":"တစ်ခုစီအတွက် လက်တွေ့လုပ်ဆောင်ချက် ရှိသည်။","en":"Provides a practical action for each pillar."},{"my":"တိုးတက်မှုကို တိုင်းတာမည့် နည်းလမ်း ပါဝင်သည်။","en":"Includes a way to measure progress."}]'::jsonb,45,1),
(7,2,'ရေရှည်တည်တံ့မှုနှင့် အသိုင်းအဝိုင်းမျှဝေမှု','Sustainability & Community Contribution','နောက် ၆ လမှ ၁၂ လအတွင်း မိမိ၏ အသက်မွေးဝမ်းကျောင်းကို ပိုမိုတည်တံ့စေရန် ရည်မှန်းချက်တစ်ခု သတ်မှတ်ပါ။ မိမိသိရှိထားသည့် ကျွမ်းကျင်မှုတစ်ခုကို အခြားသူနှင့် မည်သို့မျှဝေမည် သို့မဟုတ် အသိုင်းအဝိုင်းအတွက် မည်သည့်အကျိုးပြုမှု ပြုလုပ်နိုင်မည်ကို စီစဉ်ပါ။','Set one goal to strengthen your livelihood over the next 6–12 months. Plan how you could share one skill or contribute positively to your community.','၆–၁၂ လ ရည်မှန်းချက်၊ လုပ်ဆောင်မည့် အဆင့်များနှင့် မျှဝေ/အကျိုးပြုမည့် လုပ်ဆောင်ချက်ကို တင်ပြပါ။','Submit a 6–12 month goal, action steps and one knowledge-sharing or community contribution action.','[{"my":"ရေရှည်ရည်မှန်းချက်ကို ရှင်းလင်းစွာ ဖော်ပြထားသည်။","en":"States a clear longer-term goal."},{"my":"အဆင့်လိုက် လုပ်ဆောင်မည့်အစီအစဉ် ရှိသည်။","en":"Provides a staged action plan."},{"my":"အသိုင်းအဝိုင်းအတွက် အကျိုးပြုနိုင်မည့် နည်းလမ်းတစ်ခု ပါဝင်သည်။","en":"Identifies one realistic community contribution."}]'::jsonb,45,2)
on conflict (stage_no,activity_no) do update set
 title_my=excluded.title_my,title_en=excluded.title_en,
 instructions_my=excluded.instructions_my,instructions_en=excluded.instructions_en,
 evidence_prompt_my=excluded.evidence_prompt_my,evidence_prompt_en=excluded.evidence_prompt_en,
 assessment_criteria=excluded.assessment_criteria,
 estimated_minutes=excluded.estimated_minutes,sort_order=excluded.sort_order,is_active=true;

alter table public.livelihood_stage_activities enable row level security;
grant select on public.livelihood_stage_activities to anon, authenticated;
drop policy if exists "Anyone can read active livelihood stage activities" on public.livelihood_stage_activities;
create policy "Anyone can read active livelihood stage activities"
on public.livelihood_stage_activities for select
to anon, authenticated using (is_active = true);

comment on table public.livelihood_stage_activities is 'Bilingual practical tasks and transparent assessment criteria for each livelihood development stage.';
